import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {resolve} from 'node:path';
import {ConnectionManager} from '../../packages/core/src/connections.js';
import {DatabaseDefinitions} from '../../packages/core/src/database-definitions.js';
import {StructureComparisons} from '../../packages/core/src/structure-comparisons.js';
import {ProfileSchema,type ConnectionProfile,type DefinitionPreviewResult} from '../../packages/protocol/src/index.js';
import {ddlQuote} from '../../packages/core/src/ddl-syntax.js';
import {targetString} from '../../packages/core/src/portable-types.js';
const reviewed=(p:DefinitionPreviewResult)=>{assert.equal(p.kind,'preview');if(p.kind!=='preview')throw Error('Expected SQL preview');return p.preview;};
export async function portableStructureContract(profile:ConnectionProfile,password:string){
 const prefix='portable_'+randomUUID().replaceAll('-','').slice(0,8),server={...profile,id:prefix+'_server'},local=ProfileSchema.parse({id:prefix+'_sqlite',name:'Portable SQLite',driver:'sqlite',storage:'memory'}),profiles=[server,local],manager=new ConnectionManager({list:()=>profiles,save:async()=>{},remove:async()=>{}},{runnerPath:resolve('dist/sqlite-runner.cjs')}),definitions=new DatabaseDefinitions(manager),comparisons=new StructureComparisons(manager,definitions),d=profile.driver,mysql=d!=='postgresql',q=(n:string)=>ddlQuote(n,d),qualified=(n:string)=>q(mysql?profile.database!:'public')+'.'+q(prefix+n),from=qualified('_source'),to=qualified('_target'),literal="C:\\portable'中文\nline",defaultSql=targetString(literal,d),localLiteral=targetString(literal,'sqlite');
 await manager.setPassword(server.id,password,'session');const db=await manager.connect(server.id),sqlite=await manager.connect(local.id);
 const choose=(c:Awaited<ReturnType<StructureComparisons['compare']>>)=>c.differences.filter(v=>v.change!=='equal'&&v.selectable).map(v=>v.id);
 try{
  await sqlite.query(`CREATE TABLE local_source(id INT PRIMARY KEY,label VARCHAR(40) NOT NULL DEFAULT ${localLiteral},code VARCHAR(20) UNIQUE,n BIGINT,payload BLOB,parent INTEGER REFERENCES local_source(id) ON DELETE SET NULL,price DECIMAL(30,10) DEFAULT 5.25)`);await sqlite.query('CREATE INDEX label_index ON local_source(label DESC)');await sqlite.query("INSERT INTO local_source VALUES(2,'source','source',3,x'00',NULL,5.25)");
  await db.query(`CREATE TABLE ${to}(id BIGINT PRIMARY KEY,label VARCHAR(10),code VARCHAR(20),n BIGINT,payload ${mysql?'BLOB':'BYTEA'},parent BIGINT,price DECIMAL(10,2))`);await db.query(`INSERT INTO ${to} VALUES(7,'kept','target',9223372036854775807,${mysql?"X'00ff'":"decode('00ff','hex')"},NULL,1.25)`);
  const forward={source:{profileId:local.id,table:'local_source'},target:{profileId:server.id,table:to}},compared=await comparisons.compare(forward.source,forward.target);assert(compared.canPrepare,JSON.stringify(compared.notes));assert(compared.conversions?.every(v=>v.sql),JSON.stringify(compared.conversions));assert(compared.differences.filter(v=>v.change!=='equal').every(v=>v.requiresReview));
  const draft=await comparisons.prepare(compared.token,choose(compared)),preview=reviewed(await definitions.preview(draft.baseline,draft.sql));assert(preview.warnings.some(w=>w.includes('affinity')));assert.equal((await db.query(`SELECT label FROM ${to}`)).rows[0]?.c0,'kept');const applied=await definitions.apply(server.id,preview.token);assert.equal(applied.status,'succeeded',applied.error);
  const row=(await db.query(`SELECT id,label,n,payload,price FROM ${to} WHERE id=7`)).rows[0]!;assert.equal(row.c0,7);assert.equal(row.c1,'kept');assert.deepEqual(row.c2,{type:'integer',value:'9223372036854775807'});assert.deepEqual(row.c3,{type:'binary',base64:'AP8='});assert.equal(row.c4,'1.2500000000');assert.equal((await db.details(to)).foreignKeys.length,1);await db.query(`INSERT INTO ${to}(id,code) VALUES(8,'default')`);assert.equal((await db.query(`SELECT label FROM ${to} WHERE id=8`)).rows[0]?.c0,literal);assert.equal((await sqlite.query('SELECT label FROM local_source')).rows[0]?.c0,'source');await assert.rejects(db.query(`INSERT INTO ${to}(id,code) VALUES(9,'default')`));
  if(mysql){await db.query(`INSERT INTO ${to}(id,code,payload) VALUES(10,'large-binary',REPEAT(X'61',70000))`);assert.equal((await db.query(`SELECT OCTET_LENGTH(payload) FROM ${to} WHERE id=10`)).rows[0]?.c0,70000);}
  const fresh=await comparisons.compare(forward.source,forward.target);assert.equal(fresh.differences.filter(v=>v.kind==='column'&&v.change!=='equal').length,0,JSON.stringify(fresh.differences.filter(v=>v.kind==='column'&&v.change!=='equal')));

  await db.query(`CREATE TABLE ${from}(id BIGINT ${mysql?'PRIMARY KEY AUTO_INCREMENT':'GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY'},label VARCHAR(40) DEFAULT ${defaultSql},n BIGINT DEFAULT 9223372036854775807,payload ${mysql?"BLOB DEFAULT (X'00ff')":"BYTEA DEFAULT decode('00ff','hex')"},price DECIMAL(30,10) DEFAULT 12345678901234567890.1234567890,huge ${mysql?'BIGINT UNSIGNED':'NUMERIC(20,0)'} DEFAULT 18446744073709551615,computed INT GENERATED ALWAYS AS (7+1) STORED)`);await db.query(`INSERT INTO ${from}(id) VALUES(2)`);
  await sqlite.query('CREATE TABLE local_target(id INTEGER PRIMARY KEY,label TEXT,n INTEGER,payload BLOB,price TEXT,huge TEXT)');await sqlite.query("INSERT INTO local_target VALUES(77,'retained',9223372036854775807,X'00ff','original-cost','original-huge')");
  const backward={source:{profileId:server.id,table:from},target:{profileId:local.id,table:'local_target'}},blocked=await comparisons.compare(backward.source,backward.target),computed=blocked.differences.find(v=>v.kind==='column'&&v.name==='computed')!;assert(!computed.selectable);assert.match(computed.reason!,/Generated/);await assert.rejects(comparisons.prepare(blocked.token,[computed.id]),/unavailable/);
  const converted=await comparisons.compare(backward.source,backward.target,{computed:'"computed" INTEGER DEFAULT 5'});assert(converted.conversions?.find(v=>v.name==='computed')?.manual);const backDraft=await comparisons.prepare(converted.token,choose(converted)),backPreview=reviewed(await definitions.preview(backDraft.baseline,backDraft.sql));assert(backPreview.warnings.some(w=>w.includes('explicit target')));const backReport=await definitions.apply(local.id,backPreview.token);assert.equal(backReport.status,'succeeded',backReport.error);
  const kept=(await sqlite.query('SELECT * FROM local_target WHERE id=77')).rows[0]!;assert.deepEqual(kept,{c0:77,c1:'retained',c2:{type:'integer',value:'9223372036854775807'},c3:{type:'binary',base64:'AP8='},c4:'original-cost',c5:'original-huge',c6:5});await sqlite.query('INSERT INTO local_target DEFAULT VALUES');const defaults=(await sqlite.query('SELECT * FROM local_target WHERE id=78')).rows[0]!;assert.equal(defaults.c1,literal);assert.deepEqual(defaults.c2,{type:'integer',value:'9223372036854775807'});assert.deepEqual(defaults.c3,{type:'binary',base64:'AP8='});assert.equal(defaults.c4,'12345678901234567890.1234567890');assert.equal(defaults.c5,'18446744073709551615');assert.equal(defaults.c6,5);assert.equal((await db.query(`SELECT count(*) FROM ${from}`)).rows[0]?.c0,1);
  if(!mysql){
   await sqlite.query('CREATE TABLE identity_source(id INTEGER PRIMARY KEY)');
   for(const variant of ['maximum','negative','custom'] as const){const boundary=qualified('_identity_'+variant);try{
    await db.query(`CREATE TABLE ${boundary}(id BIGINT PRIMARY KEY)`);if(variant!=='custom')await db.query(`INSERT INTO ${boundary} VALUES(${variant==='maximum'?'9223372036854775807':'-7'})`);
    const c=await comparisons.compare({profileId:local.id,table:'identity_source'},{profileId:server.id,table:boundary}),draft=await comparisons.prepare(c.token,c.differences.filter(v=>v.change!=='equal'&&v.selectable).map(v=>v.id));
    const sql=variant==='custom'?draft.sql.replace('AS IDENTITY','AS IDENTITY (START WITH 100 INCREMENT BY 2)'):draft.sql,plan=reviewed(await definitions.preview(draft.baseline,sql)),r=await definitions.apply(server.id,plan.token);assert.equal(r.status,'succeeded',r.error);
    if(variant==='maximum'){await assert.rejects(db.query(`INSERT INTO ${boundary} DEFAULT VALUES`),/maximum value|reached maximum/);assert.deepEqual((await db.query(`SELECT id FROM ${boundary}`)).rows[0]?.c0,{type:'integer',value:'9223372036854775807'});}
    else if(variant==='negative'){await db.query(`INSERT INTO ${boundary} DEFAULT VALUES`);assert.deepEqual((await db.query(`SELECT id FROM ${boundary} ORDER BY id`)).rows,[{c0:-7},{c0:1}]);}
    else{await db.query(`INSERT INTO ${boundary} DEFAULT VALUES`);await db.query(`INSERT INTO ${boundary} DEFAULT VALUES`);assert.deepEqual((await db.query(`SELECT id FROM ${boundary} ORDER BY id`)).rows,[{c0:100},{c0:102}]);}
   }finally{await db.query(`DROP TABLE IF EXISTS ${boundary}`);}}
  }
 }finally{try{await db.query(`DROP TABLE IF EXISTS ${to}`);await db.query(`DROP TABLE IF EXISTS ${from}`);}finally{await manager.close();}}
}
